var n=`0970-samgyeopsal`;var o=`world-0970`;var a=`KR`;var s=`east-asia`;var t=4;var r=45;var g={en:`Samgyeopsal`,ua:`Самгьопсаль`};var l={en:`Samgyeopsal is a South Korea dish made with pork belly, garlic, green onion, gochujang. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Самгьопсаль, страва кухні країни Південна Корея. Основні складники: свиняча грудинка, часник, зелена цибуля, гочуджан. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`pork-belly`,920,`g`],[`garlic`,6,`clove`],[`green-onion`,115,`g`]]},{en:`Grill over medium-high heat for about 20 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 20 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:20,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`gochujang`,75,`g`],[`doenjang`,45,`g`],[`toasted-sesame-oil`,25,`ml`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`romaine-lettuce`,240,`g`],[`kimchi`,260,`g`]]}];var h={slug:n,id:o,country:`KR`,region:s,servings:4,minutes:45,title:g,text:l,steps:d};export{a as country,h as default,o as id,r as minutes,s as region,t as servings,n as slug,d as steps,l as text,g as title};